BEGIN;
CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,name text NOT NULL,email text NOT NULL UNIQUE,registration text NOT NULL DEFAULT '',password_hash text NOT NULL,verified boolean NOT NULL DEFAULT false,organizer boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),csrf text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),purpose text NOT NULL CHECK(purpose IN ('verify','reset')),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,description text NOT NULL,location text NOT NULL,timezone text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,registration_starts_at timestamptz NOT NULL,registration_ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at),CHECK(registration_ends_at>registration_starts_at));
CREATE TABLE IF NOT EXISTS organizers(user_id uuid NOT NULL REFERENCES users(id),event_id uuid NOT NULL REFERENCES events(id),PRIMARY KEY(user_id,event_id));
CREATE TABLE IF NOT EXISTS activities(id uuid PRIMARY KEY,event_id uuid NOT NULL REFERENCES events(id),title text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,minutes integer NOT NULL CHECK(minutes>0 AND minutes<=1440),checkin_starts_at timestamptz NOT NULL,checkin_ends_at timestamptz NOT NULL,is_open boolean NOT NULL DEFAULT false,CHECK(ends_at>starts_at),CHECK(checkin_ends_at>checkin_starts_at));
CREATE TABLE IF NOT EXISTS enrollments(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),event_id uuid NOT NULL REFERENCES events(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_id));
CREATE TABLE IF NOT EXISTS challenges(id uuid PRIMARY KEY,activity_id uuid NOT NULL REFERENCES activities(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS attendances(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),activity_id uuid NOT NULL REFERENCES activities(id),enrollment_id uuid NOT NULL REFERENCES enrollments(id),confirmed_at timestamptz NOT NULL DEFAULT now(),minutes integer NOT NULL CHECK(minutes>0),attempt_id uuid NOT NULL,UNIQUE(user_id,activity_id));
CREATE TABLE IF NOT EXISTS location_evidence(attendance_id uuid PRIMARY KEY REFERENCES attendances(id),latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180),accuracy double precision NOT NULL CHECK(accuracy>=0),captured_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id uuid PRIMARY KEY,actor_id uuid REFERENCES users(id),action text NOT NULL,resource_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS attendance_activity_idx ON attendances(activity_id);
CREATE INDEX IF NOT EXISTS enrollment_event_idx ON enrollments(event_id);
CREATE INDEX IF NOT EXISTS challenge_activity_idx ON challenges(activity_id);
CREATE INDEX IF NOT EXISTS location_received_idx ON location_evidence(received_at);
ALTER TABLE audit ADD COLUMN IF NOT EXISTS actor_context text NOT NULL DEFAULT 'authenticated_user';
ALTER TABLE events ADD COLUMN IF NOT EXISTS latitude double precision CHECK(latitude BETWEEN -90 AND 90);
ALTER TABLE events ADD COLUMN IF NOT EXISTS longitude double precision CHECK(longitude BETWEEN -180 AND 180);
INSERT INTO schema_migrations(version) VALUES(1),(2),(3) ON CONFLICT DO NOTHING;
COMMIT;
